  ['sfw', '日常'],
  ['口交', '口交'],
  ['性交', '性交'],
  ['肛交', '肛交'],
  ['足交', '足交'],
];

export default function CharacterGallery() {
  const [openName, setOpenName] = React.useState<string | null>(null);
  const [cat, setCat] = React.useState('sfw');
  const [lightbox, setLightbox] = React.useState<number | null>(null);
  const [imageStatus, setImageStatus] = React.useState('loading');
  const dialogRef = React.useRef<HTMLDialogElement>(null);
  const openerRef = React.useRef<HTMLButtonElement | null>(null);
  const person = openName ? GALLERY.find(g => g.name === openName) : null;
  const images = person?.behaviors[cat] || [];
  const isOpen = lightbox !== null;

  React.useEffect(() => {
    const dialog = dialogRef.current;
    if (!isOpen || !dialog) return;
    dialog.showModal();
    return () => {
      if (dialog.open) dialog.close();
      if (openerRef.current?.isConnected) openerRef.current.focus({ preventScroll: true });
    };
  }, [isOpen]);

  function moveImage(step: number) {
    if (lightbox === null) return;
    const next = Math.max(0, Math.min(images.length - 1, lightbox + step));
    if (next === lightbox) return;
    setImageStatus('loading');
    setLightbox(next);
  }

  return (
    <div className="cg">
      <style>{`
.cg{--ink:#4a3f2f;--muted:#8a7a5f;--gold:#b48a4a;--paper:#f6efe0;--line:#d9cba9;font-family:Georgia,'Noto Serif SC','Songti SC',serif;color:var(--ink);line-height:1.6;padding:14px}
.cg *{box-sizing:border-box}
.cg .head{font-size:10px;letter-spacing:.24em;color:var(--gold);margin-bottom:4px}
.cg h2{margin:0 0 12px;font-size:20px;font-weight:500;color:#3b3223}
.cg .grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:10px}
.cg .cell{background:var(--paper);border:1px solid var(--line);border-radius:6px;overflow:hidden;cursor:pointer;text-align:center;padding:8px 6px;transition:transform .15s,border-color .15s}
.cg .cell:hover{transform:translateY(-2px);border-color:var(--gold)}
.cg .cell.active{border-color:var(--gold);box-shadow:0 0 0 1px var(--gold)}
.cg .cell .ph{width:100%;aspect-ratio:3/4;object-fit:cover;border-radius:4px;background:#e9dfc8;display:block}
.cg .cell .ph-fb{width:100%;aspect-ratio:3/4;border-radius:4px;background:#e9dfc8;display:flex;align-items:center;justify-content:center;color:#a9987a;font-size:11px}
.cg .cell .nm{font-size:12px;margin-top:6px;display:block;color:#4a3f2f;font-weight:600}
.cg .cell .rt{font-size:9px;letter-spacing:.14em;color:#fff;background:var(--gold);border-radius:3px;padding:1px 7px;display:inline-block;margin-top:4px}
.cg .detail{border-top:1px solid var(--line);margin-top:14px;padding-top:14px}
.cg .detail-head{display:flex;gap:14px;align-items:flex-start;margin-bottom:12px}
.cg .detail-head .big{width:96px;height:128px;object-fit:cover;border-radius:6px;border:1px solid var(--line);background:#e9dfc8;flex-shrink:0}
.cg .detail-head .meta h3{margin:0 0 4px;font-size:17px;color:#3b3223}
.cg .detail-head .meta .id{font-size:12px;color:var(--muted);line-height:1.5}
.cg .back{font-size:12px;color:var(--gold);background:none;border:none;cursor:pointer;padding:0;margin-bottom:10px}
.cg .cats{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px}
.cg .cat{font-size:12px;padding:5px 12px;border:1px solid var(--line);border-radius:20px;background:#fff;color:var(--muted);cursor:pointer}
.cg .cat.active{background:var(--gold);color:#fff;border-color:var(--gold)}
.cg .thumbs{display:grid;grid-template-columns:repeat(auto-fill,minmax(72px,1fr));gap:8px}
.cg .thumb{aspect-ratio:3/4;object-fit:cover;border-radius:4px;border:1px solid var(--line);cursor:pointer;background:#e9dfc8;display:block;width:100%}
.cg .thumb-fb{aspect-ratio:3/4;border-radius:4px;border:1px solid var(--line);display:flex;align-items:center;justify-content:center;color:#a9987a;font-size:10px;background:#e9dfc8}
.cg .none{padding:20px;text-align:center;color:var(--muted);font-size:13px}
.cg .thumb-button{display:block;width:100%;padding:0;border:0;background:none;border-radius:4px;cursor:pointer}
.cg .thumb-button:focus-visible,.cg .lb button:focus-visible{outline:2px solid #b48a4a;outline-offset:3px}
.cg .lb{position:fixed;inset:0;margin:0;width:100%;height:100%;max-width:none;max-height:none;padding:64px 18px calc(100px + var(--sr-story-bottom-inset,0px));border:0;background:rgba(20,16,10,.96);color:#f0e6d0;display:flex;align-items:center;justify-content:center;overflow:hidden}
.cg .lb::backdrop{background:rgba(20,16,10,.7)}
.cg .lb img{display:block;max-width:100%;max-height:100%;object-fit:contain;border-radius:4px}
.cg .lb .x{position:absolute;top:10px;right:12px;width:44px;height:44px;padding:0;color:#f0e6d0;font-size:30px;cursor:pointer;background:none;border:none}
.cg .lb-controls{position:absolute;bottom:calc(18px + env(safe-area-inset-bottom,0px) + var(--sr-story-bottom-inset,0px));left:12px;right:12px;display:flex;align-items:center;justify-content:center;gap:16px;font:14px/1.5 system-ui,sans-serif}
.cg .lb-controls button{min-width:76px;min-height:44px;padding:8px 12px;border:1px solid #b48a4a;border-radius:6px;background:#3b3223;color:#f0e6d0;cursor:pointer}
.cg .lb-controls button:disabled{opacity:.35;cursor:default}
.cg .lb-count{min-width:64px;text-align:center;font-variant-numeric:tabular-nums}
.cg .lb-status{position:absolute;left:18px;right:18px;text-align:center;pointer-events:none;font:14px/1.6 system-ui,sans-serif}
`}</style>
      <div className="head">The Manor · Gallery</div>
      <h2>角色图鉴</h2>
      {!person ? (
        <div className="grid">
          {GALLERY.map(g => (
            <div
              className="cell"
              key={g.name}
              role="button"
              tabIndex={0}
              onClick={() => {
                setOpenName(g.name);
                setCat('sfw');
              }}
              onKeyDown={e => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault();
                  setOpenName(g.name);
                  setCat('sfw');
                }
              }}
            >
              {g.image ? (
                <img className="ph" src={g.image} alt={g.name} loading="lazy" />
              ) : (
                <div className="ph-fb">暂无立绘</div>
              )}
              <span className="nm">{g.name}</span>
              <span className="rt">{g.rating} 级</span>
            </div>
          ))}
        </div>
      ) : (
        <div className="detail">
          <button type="button" className="back" onClick={() => setOpenName(null)}>
            ← 返回名册
          </button>
          <div className="detail-head">
            {person.image ? (
              <img className="big" src={person.image} alt={person.name} />
            ) : (
              <div className="ph-fb" style={{ width: 96, height: 128 }}>
                暂无立绘
              </div>
            )}
            <div className="meta">
              <h3>{person.name}</h3>
              <div className="id">{person.identity}</div>
            </div>
          </div>
          <div className="cats">
            {CATS.map(([key, label]) => {
              const urls = person.behaviors[key] || [];
              if (!urls.length) return null;
              return (
                <button
                  type="button"
                  key={key}
                  className={`cat${cat === key ? ' active' : ''}`}
                  onClick={() => setCat(key)}
                >
                  {label} · {urls.length}
                </button>
              );
            })}
          </div>
          <div className="thumbs">
            {images.map((url, i) => (
              <button
                key={i}
                type="button"
                className="thumb-button"
                aria-label={`查看${person.name}的第${i + 1}张图片`}
                onClick={event => {
                  openerRef.current = event.currentTarget;
                  setImageStatus('loading');
                  setLightbox(i);
                }}
              >
                <img className="thumb" src={url} alt={`${person.name} ${cat} ${i + 1}`} loading="lazy" />
              </button>
            ))}
            {!person.behaviors[cat]?.length && (
              <div className="none">该分类暂无图片</div>
            )}
          </div>
        </div>
      )}
      {lightbox !== null && (
        <dialog
          ref={dialogRef}
          className="lb"
          aria-label={`${person?.name}图片预览`}
          onCancel={event => { event.preventDefault(); setLightbox(null); }}
          onClick={event => { if (event.target === event.currentTarget) setLightbox(null); }}
          onKeyDown={event => {
            if (event.key === 'Escape') {
              event.preventDefault(); event.stopPropagation(); setLightbox(null);
            } else if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
              event.preventDefault(); event.stopPropagation();
              moveImage(event.key === 'ArrowLeft' ? -1 : 1);
            }
          }}
        >
          <button type="button" className="x" aria-label="关闭图片预览" onClick={() => setLightbox(null)}>×</button>
          <img
            key={lightbox}
            src={images[lightbox]}
            alt={`${person?.name} 第 ${lightbox + 1} 张`}
            style={{ visibility: imageStatus === 'loaded' ? 'visible' : 'hidden' }}
            onLoad={() => setImageStatus('loaded')}
            onError={() => setImageStatus('error')}
          />
          {imageStatus !== 'loaded' && <div className="lb-status" role="status">{imageStatus === 'error' ? '图片加载失败，可以切换其他图片或关闭预览。' : '正在加载图片…'}</div>}
          <div className="lb-controls">
            <button type="button" disabled={lightbox === 0} onClick={() => moveImage(-1)}>上一张</button>
            <span className="lb-count" aria-live="polite">{lightbox + 1} / {images.length}</span>
            <button type="button" disabled={lightbox === images.length - 1} onClick={() => moveImage(1)}>下一张</button>
          </div>
        </dialog>
      )}
    </div>
  );
}

