export default function CGImage({ groups }: { groups?: Array<string | undefined> }) {
  const name = groups?.[0];
  const behavior = groups?.[1];
  const num = parseInt(groups?.[2] || '', 10);
  if (!name || !behavior || !Number.isFinite(num) || num < 1) return null;
  const person = GALLERY.find(g => g.name === name);
  if (!person) return null;
  const urls = person.behaviors?.[behavior] || [];
  const url = urls[num - 1];
  if (!url) return null;
  return (
    <img
      src={url}
      alt={`${name} · ${behavior} · ${num}`}
      loading="lazy"
      style={{ maxWidth: '100%', borderRadius: 6, display: 'block', margin: '10px 0' }}
    />
  );
}

